using System.ComponentModel.DataAnnotations;

namespace sv_1fb540d3e1114547b1ce6b1682fe9a8b.Models;

// Domain records
public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

// Mutable form models for two-way binding
public class PersonalInfoModel
{
    [Required(ErrorMessage = "Full name is required.")]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = "";

    [Required(ErrorMessage = "Phone number is required.")]
    [Phone(ErrorMessage = "Please enter a valid phone number.")]
    public string Phone { get; set; } = "";

    [Required(ErrorMessage = "Address is required.")]
    public string Address { get; set; } = "";
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
}

.step-indicator {
    padding: 1rem 0;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    flex: 1;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    margin-bottom: 0.5rem;
    background: #e9ecef;
    color: #adb5bd;
    transition: all 0.2s;
    position: relative;
    z-index: 1;
}

.step-item.active .step-circle {
    background: #0d6efd;
    color: #fff;
    box-shadow: 0 0 0 4px rgba(13, 110, 253, 0.2);
}

.step-item.completed .step-circle {
    background: #198754;
    color: #fff;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #adb5bd;
    max-width: 90px;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-connector {
    position: absolute;
    top: 18px;
    left: calc(50% + 22px);
    width: calc(100% - 44px);
    height: 2px;
    background: #dee2e6;
    z-index: 0;
}

.step-connector.completed {
    background: #198754;
}

@using sv_1fb540d3e1114547b1ce6b1682fe9a8b.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Position @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">
                    Remove
                </button>
            }
        </div>

        <div class="row">
            <div class="col-md-6 mb-3">
                <label class="form-label">Company <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Entry.Company" @bind:event="oninput" />
            </div>
            <div class="col-md-6 mb-3">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="Entry.Title" @bind:event="oninput" />
            </div>
        </div>

        <div class="row align-items-end">
            <div class="col-md-4 mb-3">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" @bind="Entry.StartDate" />
            </div>
            <div class="col-md-4 mb-3">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" @bind="Entry.EndDate" disabled="@Entry.IsCurrent" />
            </div>
            <div class="col-md-4 mb-3">
                <div class="form-check">
                    <input type="checkbox" class="form-check-input" id="@_currentId"
                           checked="@Entry.IsCurrent" @onchange="HandleCurrentChanged" />
                    <label class="form-check-label" for="@_currentId">Currently working here</label>
                </div>
            </div>
        </div>

        <div class="mb-0">
            <label class="form-label">Description</label>
            <textarea class="form-control" rows="3" @bind="Entry.Description" @bind:event="oninput"></textarea>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public WorkEntryModel Entry { get; set; } = default!;

    [Parameter]
    public int Index { get; set; }

    [Parameter]
    public bool CanRemove { get; set; }

    [Parameter]
    public EventCallback OnRemove { get; set; }

    private string _currentId => $"current-{Index}";

    private void HandleCurrentChanged(ChangeEventArgs e)
    {
        Entry.IsCurrent = (bool)(e.Value ?? false);
        if (Entry.IsCurrent)
        {
            Entry.EndDate = null;
        }
    }
}

