    <div class="mb-3">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <InputText @bind-Value="Model.Address" class="form-control" placeholder="123 Main St, City, State" />
        <ValidationMessage For="() => Model.Address" />
    </div>

    <div class="d-flex justify-content-end">
        <button type="submit" class="btn btn-primary" disabled="@_validating">
            @if (_validating)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Next
        </button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired]
    public PersonalInfoModel Model { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback OnNext { get; set; }

    [Parameter, EditorRequired]
    public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? _emailError;
    private bool _validating;

    private async Task HandleNext()
    {
        _emailError = null;
        _validating = true;

        try
        {
            var isValid = await ValidateEmail(Model.Email);
            if (!isValid)
            {
                _emailError = "This email address could not be verified.";
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            _validating = false;
        }
    }
}

