@using sv_1fb540d3e1114547b1ce6b1682fe9a8b.Models

@if (SubmittedId.HasValue)
{
    <div class="text-center py-5">
        <div class="mb-3">
            <span class="display-1 text-success">✓</span>
        </div>
        <h3 class="text-success">Application Submitted!</h3>
        <p class="lead">Your application ID is <strong>#@SubmittedId</strong></p>
        <p class="text-muted">We'll review your application and get back to you soon.</p>
    </div>
}
else
{
    <h4 class="mb-4">Review Your Application</h4>

    @* Personal Information *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Personal Information</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-3">Name</dt>
                <dd class="col-sm-9">@PersonalInfo.FullName</dd>
                <dt class="col-sm-3">Email</dt>
                <dd class="col-sm-9">@PersonalInfo.Email</dd>
                <dt class="col-sm-3">Phone</dt>
                <dd class="col-sm-9">@PersonalInfo.Phone</dd>
                <dt class="col-sm-3">Address</dt>
                <dd class="col-sm-9 mb-0">@PersonalInfo.Address</dd>
            </dl>
        </div>
    </div>

    @* Work History *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Work History</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var entry in WorkEntries)
            {
                <div class="mb-3 pb-3 border-bottom last-no-border">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <small class="text-muted">
                        @entry.StartDate?.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mt-1 mb-0">@entry.Description</p>
                    }
                </div>
            }
        </div>
    </div>

    @* References *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">References</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var r in References)
            {
                <div class="mb-2">
                    <strong>@r.Name</strong> — @r.Relationship
                    <br />
                    <small class="text-muted">@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"· {r.Phone}" : "")</small>
                </div>
            }
        </div>
    </div>

    @* Cover Letter *@
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Cover Letter</h5>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
        </div>
        <div class="card-body">
            @if (string.IsNullOrWhiteSpace(CoverLetter))
            {
                <p class="text-muted fst-italic mb-0">No cover letter provided.</p>
            }
            else
            {
                <p class="mb-0" style="white-space: pre-wrap;">@CoverLetter</p>
            }
        </div>
    </div>

    @if (_submitError is not null)
    {
        <div class="alert alert-danger">@_submitError</div>
    }

    <div class="d-flex justify-content-between">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Submit Application
        </button>
    </div>
}

@code {
    [Parameter, EditorRequired]
    public PersonalInfoModel PersonalInfo { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<WorkEntryModel> WorkEntries { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<ReferenceModel> References { get; set; } = default!;

    [Parameter]
    public string CoverLetter { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<int> OnEditStep { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnSubmit { get; set; }

    [Parameter]
    public bool IsSubmitting { get; set; }

    [Parameter]
    public int? SubmittedId { get; set; }

    private string? _submitError;

    private async Task HandleSubmit()
    {
        _submitError = null;
        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
    }
}

@page "/apply"
@rendermode InteractiveServer
@using sv_1fb540d3e1114547b1ce6b1682fe9a8b.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (_currentStep)
        {
            case 1:
                <PersonalInfoStep Model="_personalInfo"
                                  OnNext="CompleteCurrentAndAdvance"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync" />
                break;
            case 2:
                <WorkHistoryStep Entries="_workEntries"
                                 OnNext="CompleteCurrentAndAdvance"
                                 OnBack="PreviousStep" />
                break;
            case 3:
                <ReferencesStep References="_references"
                                OnNext="CompleteCurrentAndAdvance"
                                OnBack="PreviousStep" />
                break;
            case 4:
                <CoverLetterStep @bind-CoverLetter="_coverLetter"
                                 OnNext="CompleteCurrentAndAdvance"
                                 OnBack="PreviousStep" />
                break;
            case 5:
                <ReviewStep PersonalInfo="_personalInfo"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="@_coverLetter"
                            OnBack="PreviousStep"
                            OnEditStep="GoToStep"
                            OnSubmit="HandleSubmit"
                            IsSubmitting="_isSubmitting"
                            SubmittedId="_submittedId" />
                break;
        }
    </div>
</div>

@code {
    private int _currentStep = 1;
    private readonly HashSet<int> _completedSteps = [];

    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = [new()];
    private readonly List<ReferenceModel> _references = [new()];
    private string _coverLetter = "";

    private bool _isSubmitting;
    private int? _submittedId;

    private void CompleteCurrentAndAdvance()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void PreviousStep() => _currentStep--;

    private void GoToStep(int step) => _currentStep = step;

    private async Task HandleSubmit()
    {
        _isSubmitting = true;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(
                    _personalInfo.FullName,
                    _personalInfo.Email,
                    _personalInfo.Phone,
                    _personalInfo.Address),
                new WorkHistory(
                    _workEntries.Select(e => new WorkEntry(
                        e.Company,
                        e.Title,
                        e.StartDate!.Value,
                        e.IsCurrent ? null : e.EndDate,
                        e.Description)).ToList()),
                _references.Select(r => new Reference(
                    r.Name,
                    r.Relationship,
                    r.Email,
                    r.Phone)).ToList(),
                _coverLetter);

            _submittedId = await ApplicationService.SubmitApplicationAsync(application);
            _completedSteps.Add(5);
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

